/**
 * The compiled first-grant form against the two things that have to agree with
 * it: the runtime registry it was generated from, and the handler that reads
 * what it submits.
 *
 * The form is generated by the compiler (packages/compiler/src/record-action-grants.ts)
 * and read by `grantAssignment` (operations.ts) through one naming rule stated
 * in two packages. A drift between them would not fail a compile — it would
 * produce a form whose values the handler cannot find — so it is asserted
 * here, against the artifact an actual `bun run generate` produced.
 *
 * Validation uses the API's own Operation validator, so what passes here is
 * what a request passes.
 */
import { describe, expect, test } from "bun:test";
import catalog from "../../generated/operations/catalog.json" with { type: "json" };
import pageConfigs from "../../generated/page-configs/entity-page-configs.seed.json" with { type: "json" };
import { createOperationAjv } from "../operation-ajv.js";
import { fieldNameForColumn } from "../entity/columns.js";
import {
  RECORD_ACTION_GRANT_TARGET,
  recordActionAssignmentEntities,
  recordActionGrantInputs,
} from "./registry.js";

type CompiledOperation = {
  key: string;
  handler: string;
  inputSchema: Record<string, any>;
  auth: { mode: string; roles?: string[] };
  effects: { data: string };
};

const operations = (catalog as { operations: CompiledOperation[] }).operations;
const grant = operations.find((operation) => operation.key === "record-actions.grant-assignment");
const registry = recordActionAssignmentEntities();

/**
 * Which registry entities this deployment actually projects a web collection
 * for, read from the generated page configs rather than from the form under
 * test — an entity with no collection has no page config seeded for its slug.
 *
 * It is the one narrowing the FORM adds over the runtime registry
 * (packages/compiler/src/record-action-grants.ts): the reference picker
 * populates itself from the target's own collection, so an entity that
 * projects none has nothing for the control to query. The registry stays the
 * authority — a locator naming an unoffered entity is still resolved and
 * still refused on its own merits — so the form is a subset and never a
 * superset, which is what the two expectations below say.
 */
const webEntitySlugs = new Set(
  (pageConfigs as { rows: { entitySlug: string }[] }).rows.map((row) => row.entitySlug));
const offered = registry.filter((entity) =>
  webEntitySlugs.has(entity.table.source?.authoringEntitySlug ?? ""));
const withheld = registry.filter((entity) => !offered.includes(entity));

const validate = createOperationAjv().compile(grant!.inputSchema);

const RECORD = "22222222-2222-4222-8222-222222222222";

/** One variant of the generated form, as the handler reads it. */
function target(entity: string, action: string): Record<string, unknown> {
  const names = recordActionGrantInputs(entity);
  return { entity, [names.record]: RECORD, [names.action]: action };
}

/** A first grant of one declared action of one registry entity. */
function submission(entity: string, action: string): Record<string, unknown> {
  return {
    integrationId: "11111111-1111-4111-8111-111111111111",
    [RECORD_ACTION_GRANT_TARGET]: target(entity, action),
  };
}

/** The branch of the generated variant that fixes this entity. */
function branch(entity: string): Record<string, any> {
  return grant!.inputSchema.properties[RECORD_ACTION_GRANT_TARGET].oneOf
    .find((candidate: any) => candidate.properties.entity.const === entity);
}

describe("the generated grant form", () => {
  test("is one Operation, on the one handler, with the surface's own authority", () => {
    expect(grant).toBeDefined();
    expect(grant!.handler).toBe("grantAssignment");
    expect(grant!.auth).toMatchObject({ mode: "session", roles: ["Platform.ApiKeys.Manage"] });
    expect(grant!.effects.data).toBe("write");
    // And it is the only grant Operation: the per-entity forms it replaced
    // would each have been one more surface to authorize.
    expect(operations.filter((operation) => operation.handler === "grantAssignment")).toHaveLength(1);
  });

  test("offers every registry entity it has a collection to pick from, and no other", () => {
    expect(offered.length).toBeGreaterThan(1);
    const variants = grant!.inputSchema.properties[RECORD_ACTION_GRANT_TARGET].oneOf;
    // Never MORE than the registry — a choice the handler would refuse — and
    // never fewer than the registry entities that have a collection.
    expect(variants.map((candidate: any) => candidate.properties.entity.const))
      .toEqual(offered.map((entity) => entity.entity));
    // The ones left out are left out for the one documented reason, and the
    // registry still admits them: this is a narrower form, not a narrower
    // authority.
    for (const entity of withheld) {
      expect([entity.entity, webEntitySlugs.has(entity.table.source?.authoringEntitySlug ?? "")])
        .toEqual([entity.entity, false]);
    }
    expect(grant!.inputSchema.required)
      .toEqual(["integrationId", RECORD_ACTION_GRANT_TARGET]);
    expect(grant!.inputSchema.additionalProperties).toBe(false);
    // The variant is ONE input, a level below the root: a generic operation
    // form lays out the root properties as its fields and does not resolve a
    // branch beside them, so a root-level `oneOf` would render every entity's
    // picker and every entity's action list at once.
    expect(Object.keys(grant!.inputSchema.properties).sort())
      .toEqual(["confirmed", "integrationId", RECORD_ACTION_GRANT_TARGET].sort());
    expect(grant!.inputSchema.oneOf).toBeUndefined();
    // And the integration stays a ROOT input, which is the one a collection
    // action's route binding can fill.
    expect(grant!.inputSchema.properties.integrationId.format).toBe("uuid");
  });

  test("declares, per entity, the inputs the handler reads and that entity's own picker", () => {
    for (const entity of offered) {
      const names = recordActionGrantInputs(entity.entity);
      const properties = branch(entity.entity).properties;
      // The picker submits the key the locator and the canonical writer
      // address a record by — read from the same manifest the runtime registry
      // reads, so the form cannot offer a value the handler cannot resolve.
      const key = entity.table.columns.find((column) => column.name === entity.keyColumn)!;
      expect(key.type).toBe("uuid");
      expect(properties[names.record]["x-osf-reference"])
        .toEqual({ entity: entity.entity, valueField: fieldNameForColumn(key) });
      expect(properties[names.record].format).toBe("uuid");
      // Exactly the actions this entity declared for an application, which is
      // what the canonical writer will accept and nothing more.
      expect(properties[names.action].enum)
        .toEqual(entity.actions.map((action) => action.name));
      // The discriminator and this variant's two inputs, all required: a
      // half-filled branch is a validation error rather than a grant on
      // whatever the form carried.
      expect(branch(entity.entity).required)
        .toEqual(["entity", names.record, names.action]);
      // No other variant's inputs are in this branch.
      expect(Object.keys(properties)).toEqual(["entity", names.record, names.action]);
    }
  });

  test("is a discriminated choice a generic variant control can resolve", () => {
    // The host finds the branch by the one property every branch states a
    // different `const` for, labels the choice from the branch's own title,
    // and refuses two branches that use one reference input name for
    // different targets. All three are facts about this generated schema.
    const variants = grant!.inputSchema.properties[RECORD_ACTION_GRANT_TARGET].oneOf;
    const names = Object.keys(variants[0].properties).filter((key: string) => {
      const consts = variants.map((candidate: any) => candidate.properties[key]?.const);
      return consts.every((value: unknown) => value !== undefined) &&
        new Set(consts).size === variants.length;
    });
    expect(names).toEqual(["entity"]);
    const references = variants.flatMap((candidate: any) => Object.entries(candidate.properties)
      .filter(([, field]) => (field as any)["x-osf-reference"]).map(([name]) => name));
    expect(new Set(references).size).toBe(references.length);
    for (const candidate of variants) {
      expect(candidate["x-osf-i18n"].title.en.length).toBeGreaterThan(0);
      expect(candidate["x-osf-i18n"].title.nl.length).toBeGreaterThan(0);
    }
  });

  test("every choice a reader sees carries a label in both languages", () => {
    const labels = (annotation: Record<string, { en?: string; nl?: string }>) =>
      Object.values(annotation).every((text) => Boolean(text.en?.trim() && text.nl?.trim()));
    const titles = Object.fromEntries(
      grant!.inputSchema.properties[RECORD_ACTION_GRANT_TARGET].oneOf.map((candidate: any) =>
        [candidate.properties.entity.const, candidate["x-osf-i18n"].title]));
    expect(Object.keys(titles)).toEqual(offered.map((entity) => entity.entity));
    expect(labels(titles)).toBe(true);
    for (const entity of offered) {
      const names = recordActionGrantInputs(entity.entity);
      const action = branch(entity.entity).properties[names.action];
      expect(Object.keys(action["x-osf-i18n"].enum))
        .toEqual(entity.actions.map((candidate) => candidate.name));
      expect(labels(action["x-osf-i18n"].enum)).toBe(true);
    }
  });
});

describe("the form's variants, through the API's own validator", () => {
  test("one variant's record and action are accepted", () => {
    for (const entity of offered) {
      expect(validate(submission(entity.entity, entity.actions[0]!.name))).toBe(true);
    }
  });

  test("a switched record type must bring its own record and action", () => {
    const [first, second] = offered as [typeof offered[number], typeof offered[number]];
    // The record type of one variant with the inputs of another: refused by
    // the validator, before the handler, which is what makes a half-switched
    // form a validation error rather than a grant on whatever was left behind.
    expect(validate({ integrationId: "11111111-1111-4111-8111-111111111111",
      [RECORD_ACTION_GRANT_TARGET]: {
        ...target(second.entity, second.actions[0]!.name), entity: first.entity,
      } })).toBe(false);
    // A branch with no record and no action at all, and one with no record
    // type named: equally refused.
    expect(validate({ integrationId: "11111111-1111-4111-8111-111111111111",
      [RECORD_ACTION_GRANT_TARGET]: { entity: first.entity } })).toBe(false);
    const { entity: _unnamed, ...withoutType } = target(first.entity, first.actions[0]!.name);
    expect(validate({ integrationId: "11111111-1111-4111-8111-111111111111",
      [RECORD_ACTION_GRANT_TARGET]: withoutType })).toBe(false);
    // The same switch completed: accepted again.
    expect(validate(submission(first.entity, first.actions[0]!.name))).toBe(true);
  });

  test("an unknown record type, an undeclared action and an unknown input are refused", () => {
    const [first] = offered as [typeof offered[number]];
    expect(validate({ integrationId: "11111111-1111-4111-8111-111111111111",
      [RECORD_ACTION_GRANT_TARGET]: {
        ...target(first.entity, first.actions[0]!.name), entity: "Relation",
      } })).toBe(false);
    expect(validate(submission(first.entity, "publish"))).toBe(false);
    // A record that is not of the shape every variant's key has.
    const names = recordActionGrantInputs(first.entity);
    expect(validate({ integrationId: "11111111-1111-4111-8111-111111111111",
      [RECORD_ACTION_GRANT_TARGET]: {
        ...target(first.entity, first.actions[0]!.name), [names.record]: "not-a-uuid",
      } })).toBe(false);
    // The closed root refuses an input no variant declares.
    expect(validate({ ...submission(first.entity, first.actions[0]!.name), recordId: RECORD }))
      .toBe(false);
    expect(validate({ ...submission(first.entity, first.actions[0]!.name), entity: first.entity }))
      .toBe(false);
    // The integration comes from the route, and it is not optional.
    const { integrationId: _bound, ...withoutIntegration } =
      submission(first.entity, first.actions[0]!.name);
    expect(validate(withoutIntegration)).toBe(false);
    expect(validate({ integrationId: "11111111-1111-4111-8111-111111111111" })).toBe(false);
  });

  test("a leftover input of another variant validates, and the handler ignores it", () => {
    // The nested object is not closed: a branch declares the properties it
    // requires, and JSON Schema keeps `additionalProperties` to the schema
    // that declares them. So a submission that still carries the other
    // variant's record passes — and acts on NOTHING but the named type's
    // inputs, by the same rule the compiler generated them with
    // (`grantAssignment` in operations.ts, exercised against a database in
    // assignments-db.test.ts).
    const [first, second] = offered as [typeof offered[number], typeof offered[number]];
    expect(validate({ integrationId: "11111111-1111-4111-8111-111111111111",
      [RECORD_ACTION_GRANT_TARGET]: {
        ...target(first.entity, first.actions[0]!.name),
        ...target(second.entity, second.actions[0]!.name),
        entity: first.entity,
      } })).toBe(true);
  });
});
